class Solution {
public:
    int threeSumClosest(vector<int>& a, int t) {
        sort(a.begin(), a.end());
        int n = a.size(), best = a[0] + a[1] + a[2];
        for (int i = 0; i + 2 < n; i++) {
            int l = i + 1, r = n - 1;
            while (l < r) {
                int s = a[i] + a[l] + a[r];
                if (abs(s - t) < abs(best - t)) best = s;
                if (s < t) l++;
                else if (s > t) r--;
                else return s;
            }
        }
        return best;
    }
};
