class Solution {
public:
    int triangleNumber(vector<int>& a) {
        sort(a.begin(), a.end());
        int cnt = 0;
        for (int k = (int)a.size() - 1; k >= 2; k--) {
            int l = 0, r = k - 1;
            while (l < r) {
                if (a[l] + a[r] > a[k]) { cnt += r - l; r--; }
                else l++;
            }
        }
        return cnt;
    }
};
